import hashlib
import hmac
import time
import json
import re
from typing import Optional, Dict, Any
from dataclasses import dataclass, field
from urllib.parse import urlparse, parse_qs
import secrets

# Secure session token generation
SECRET_KEY = secrets.token_bytes(32)
SESSION_DURATION = 3600

@dataclass
class User:
    user_id: int
    username: str
    role: str
    permissions: list = field(default_factory=list)

@dataclass  
class Session:
    token: str
    user_id: int
    role: str
    expires_at: float
    metadata: Dict[str, Any] = field(default_factory=dict)


class TokenService:
    """Handles secure token generation and validation using HMAC."""

    def __init__(self, secret: bytes):
        self._secret = secret
        self._sessions: Dict[str, Session] = {}

    def create_session(self, user: User, metadata: Optional[Dict] = None) -> str:
        """Create a new authenticated session."""
        expires_at = time.time() + SESSION_DURATION
        payload = f"{user.user_id}:{user.role}:{expires_at}"
        signature = hmac.new(self._secret, payload.encode(), hashlib.sha256).hexdigest()
        token = f"{payload}:{signature}"

        session = Session(
            token=token,
            user_id=user.user_id,
            role=user.role,
            expires_at=expires_at,
            metadata=metadata or {}
        )
        self._sessions[token] = session
        return token

    def validate_token(self, token: str) -> Optional[Session]:
        """Validate token integrity and expiration."""
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None

        payload, provided_sig = parts
        expected_sig = hmac.new(self._secret, payload.encode(), hashlib.sha256).hexdigest()

        # Constant-time comparison to prevent timing attacks
        if not hmac.compare_digest(provided_sig, expected_sig):
            return None

        session = self._sessions.get(token)
        if session and session.expires_at > time.time():
            return session
        return None


class AccessControl:
    """Role-based access control with hierarchical permissions."""

    ROLE_HIERARCHY = {
        'admin': 100,
        'manager': 50,
        'user': 10,
        'guest': 0
    }

    RESOURCE_REQUIREMENTS = {
        '/api/admin/users': ('admin', 100),
        '/api/admin/config': ('admin', 100),
        '/api/reports': ('manager', 50),
        '/api/data': ('user', 10),
        '/api/public': ('guest', 0),
    }

    def check_access(self, session: Session, resource_path: str) -> bool:
        """Check if session has access to the requested resource."""
        # Normalize the path
        normalized = self._normalize_path(resource_path)

        # Find matching resource requirement
        requirement = self._find_requirement(normalized)
        if requirement is None:
            return False  # Deny by default

        required_role, required_level = requirement
        session_level = self.ROLE_HIERARCHY.get(session.role, 0)

        return session_level >= required_level

    def _normalize_path(self, path: str) -> str:
        """Normalize URL path to prevent traversal attacks."""
        # Parse and reconstruct to handle encoded characters
        parsed = urlparse(path)
        # Remove double slashes, trailing slashes, and resolve . and ..
        segments = [s for s in parsed.path.split('/') if s and s != '.']
        resolved = []
        for seg in segments:
            if seg == '..':
                if resolved:
                    resolved.pop()
            else:
                resolved.append(seg)
        return '/' + '/'.join(resolved)

    @staticmethod
    def _path_matches(path: str, resource: str) -> bool:
        """Return True only if `path` is `resource` or a sub-path of it,
        respecting path segment boundaries (prevents prefix-confusion)."""
        if path == resource:
            return True
        # Ensure the match ends on a path segment boundary
        prefix = resource if resource.endswith('/') else resource + '/'
        return path.startswith(prefix)

    def _find_requirement(self, path: str) -> Optional[tuple]:
        """Find the most specific matching requirement for a path."""
        best_match = None
        best_length = 0

        for resource, requirement in self.RESOURCE_REQUIREMENTS.items():
            if self._path_matches(path, resource) and len(resource) > best_length:
                best_match = requirement
                best_length = len(resource)

        return best_match


class RequestHandler:
    """Handles incoming API requests with authentication and authorization."""

    def __init__(self):
        self.token_service = TokenService(SECRET_KEY)
        self.access_control = AccessControl()
        self._rate_limits: Dict[str, list] = {}

    def _check_rate_limit(self, client_id: str, max_requests: int = 100, window: int = 60) -> bool:
        """Rate limiting using sliding window."""
        now = time.time()
        if client_id not in self._rate_limits:
            self._rate_limits[client_id] = []

        # Remove old entries
        self._rate_limits[client_id] = [
            t for t in self._rate_limits[client_id] if t > now - window
        ]

        if len(self._rate_limits[client_id]) >= max_requests:
            return False

        self._rate_limits[client_id].append(now)
        return True

    def handle_request(self, method: str, path: str, headers: Dict[str, str], 
                       body: Optional[str] = None) -> Dict[str, Any]:
        """Process an incoming request."""
        # Extract client identifier for rate limiting
        client_id = headers.get('X-Forwarded-For', headers.get('Remote-Addr', 'unknown'))

        if not self._check_rate_limit(client_id):
            return {'status': 429, 'body': 'Rate limit exceeded'}

        # Authenticate
        auth_header = headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return {'status': 401, 'body': 'Missing authentication'}

        token = auth_header[7:]  # Strip 'Bearer '
        session = self.token_service.validate_token(token)

        if session is None:
            return {'status': 401, 'body': 'Invalid or expired token'}

        # Authorize
        if not self.access_control.check_access(session, path):
            return {'status': 403, 'body': 'Access denied'}

        # Route to handler
        return self._route_request(method, path, session, body)

    def _route_request(self, method: str, path: str, session: Session, 
                       body: Optional[str]) -> Dict[str, Any]:
        """Route authenticated request to appropriate handler."""
        normalized = self.access_control._normalize_path(path)

        if self.access_control._path_matches(normalized, '/api/admin/users') and method == 'GET':
            return self._handle_list_users(session)
        elif self.access_control._path_matches(normalized, '/api/admin/config') and method == 'POST':
            return self._handle_update_config(session, body)
        elif self.access_control._path_matches(normalized, '/api/data') and method == 'GET':
            return self._handle_get_data(session, path)

        return {'status': 404, 'body': 'Not found'}

    def _handle_list_users(self, session: Session) -> Dict[str, Any]:
        """Admin endpoint to list users."""
        return {'status': 200, 'body': json.dumps([{'id': 1, 'name': 'admin'}])}

    def _handle_update_config(self, session: Session, body: Optional[str]) -> Dict[str, Any]:
        """Admin endpoint to update configuration."""
        if not body:
            return {'status': 400, 'body': 'Missing body'}
        try:
            config = json.loads(body)
        except json.JSONDecodeError:
            return {'status': 400, 'body': 'Invalid JSON'}
        return {'status': 200, 'body': 'Config updated'}

    def _handle_get_data(self, session: Session, path: str) -> Dict[str, Any]:
        """User endpoint to get data with query parameters."""
        parsed = urlparse(path)
        params = parse_qs(parsed.query)

        # Build safe parameterized query
        filters = {}
        if 'id' in params:
            try:
                filters['id'] = int(params['id'][0])
            except (ValueError, IndexError):
                return {'status': 400, 'body': 'Invalid id parameter'}

        if 'name' in params:
            # Validate name parameter - alphanumeric only
            name = params['name'][0]
            if not re.match(r'^[a-zA-Z0-9_]{1,64}$', name):
                return {'status': 400, 'body': 'Invalid name parameter'}
            filters['name'] = name

        return {'status': 200, 'body': json.dumps({'filters': filters, 'results': []})}


class PermissionEscalationGuard:
    """Additional security layer that validates permission changes."""

    def __init__(self, token_service: TokenService):
        self._token_service = token_service
        self._audit_log: list = []

    def elevate_session(self, token: str, target_role: str, 
                        admin_token: str) -> Optional[str]:
        """Allow an admin to elevate another session's role.

        Security: Only admins can elevate, and cannot elevate beyond their own level.
        """
        # Validate admin session
        admin_session = self._token_service.validate_token(admin_token)
        if admin_session is None:
            return None

        if admin_session.role != 'admin':
            return None

        # Validate target session
        target_session = self._token_service.validate_token(token)
        if target_session is None:
            return None

        # Check target role is valid
        valid_roles = AccessControl.ROLE_HIERARCHY
        if target_role not in valid_roles:
            return None

        # SECURITY CHECK: Verify the target role level does not exceed admin's
        target_level = valid_roles[target_role]
        admin_level = valid_roles.get(admin_session.role, 0)

        # Strictly prevent elevation to same or higher level
        if target_level >= admin_level:
            return None

        # Update session role
        target_session.role = target_role

        self._audit_log.append({
            'action': 'elevate',
            'admin_id': admin_session.user_id,
            'target_id': target_session.user_id,
            'new_role': target_role,
            'timestamp': time.time()
        })

        return token

    def get_audit_log(self, admin_token: str) -> Optional[list]:
        """Retrieve audit log (admin only)."""
        session = self._token_service.validate_token(admin_token)
        if session and session.role == 'admin':
            return self._audit_log.copy()
        return None
